/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.application;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.feature.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.feature.oauth.consent.domain.gateway.ScopeApprovalGateway;

/**
 * Application service for scope approval flows.
 *
 * <p>
 * Determines which requested scopes still need the user's explicit approval (mandatory or
 * optional), and stores the user's decision after the approval form is submitted.
 *
 * <p>
 * Delegates persistence and business logic to {@link ScopeApprovalGateway}.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ScopeApprovalUsecase {

  private final ScopeApprovalGateway gateway;

  /**
   * Returns the scopes that require explicit user approval.
   *
   * <p>
   * Normalizes the raw scope string before forwarding to the gateway. Returns an empty list when no
   * approval is needed.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param scopeString raw scope string from the authorization request
   * @param completedChallenges challenges already satisfied in this authentication flow
   * @return pending scopes requiring approval; empty list if none
   */
  public List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      String scopeString, List<AuthenticationChallenge> completedChallenges) {
    List<String> scopes = normalizeScopes(scopeString);
    return gateway.pendingApprovals(tenant, username, clientId, scopes, completedChallenges);
  }

  /**
   * Scopes the user decides on again ({@code prompt=consent}, task 1.6): the pending ones as the
   * gateway describes them, followed by every other requested scope as an optional one, already
   * consented.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param scopeString raw scope string from the authorization request
   * @param completedChallenges challenges already satisfied in this authentication flow
   * @return every requested scope, the pending ones first
   */
  public List<ScopePermission> renewedApprovals(String tenant, String username, String clientId,
      String scopeString, List<AuthenticationChallenge> completedChallenges) {
    List<ScopePermission> result = new ArrayList<>(
        pendingApprovals(tenant, username, clientId, scopeString, completedChallenges));
    Set<String> listed = result.stream().map(ScopePermission::getScope).collect(Collectors.toSet());
    normalizeScopes(scopeString)
        .stream().filter(scope -> !listed.contains(scope)).map(scope -> ScopePermission.builder()
            .scope(scope).required(false).label(scope).description(scope).build())
        .forEach(result::add);
    return result;
  }

  /**
   * Withdraws the stored consent of the scopes the user left unchecked when deciding again.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param scopes scopes not accepted again
   */
  public void withdrawScopes(String tenant, String username, String clientId, List<String> scopes) {
    gateway.withdrawScopes(tenant, username, clientId, scopes);
  }

  /**
   * Persists the scopes accepted by the user.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param acceptedScopes scopes explicitly accepted by the user
   */
  public void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes) {
    gateway.storeApprovedScopes(tenant, username, clientId, acceptedScopes);
  }

  private List<String> normalizeScopes(String scopeString) {
    if (null == scopeString || scopeString.isBlank()) {
      return List.of();
    }
    return Arrays.stream(scopeString.split("\\s+")).filter(s -> !s.isBlank()).distinct()
        .collect(Collectors.toList());
  }
}
